\begin{abstract}
We report a machine-verified formalization in Lean~4 (\texttt{Mathlib}) showing that a single binary idempotent $P^2 = P$ in an arbitrary characteristic-free non-commutative ring $B$ canonically generates a self-contained algebraic geometry uniting eight structures normally treated in separate disciplines: (1) a split-quaternion $\mathcal{C}\ell_{1,1}$ Tetraktys $(\Phi, J, V, \Sigma)$ where the phase axis $J^2 = -V$ and metric/mass scale $\Phi^2 = +V = \{N_+, N_-\}$ emerge without scalar complex numbers; (2) an off-shell homogenization of the $\mathbb{Z}_2 \times \mathbb{Z}_2$ Klein--Hadamard character projectors ($\widetilde{\Pi}_\alpha \circ \widetilde{\Pi}_\beta = 8\delta_{\alpha\beta} V^2 \widetilde{\Pi}_\alpha$) valid without idempotency or invertibility assumptions on $V$; (3) a division-free Hodge--De~Rham cochain complex ($d_\pm^2 = \bar{d}_\pm^2 = 0$, $\bar{d}_\pm = -\star d_\pm \star$) whose Laplacian $\{d_\Phi, \bar{d}_\Phi\}(X) = 2VX$ generates pure left-multiplication by the metric $V$; (4) an exact Lindblad/Connes--Higgs double-commutator trinity $2\mathcal{D}_{\mathrm{sym}}(X) = -[\Phi, [\Phi, X]] + [J, [J, X]]$ with eigenvalue gap $-4V$; (5) a non-commutative Golden--Cyclotomic Galois bridge where $P + \Phi$ satisfies $\delta(P + \Phi) = +V$ (discriminant $1 + 4V$) while $\omega_J = -(P + J)$ satisfies $\Phi_3(\omega_J) = 1 - V$ (discriminant $1 - 4V$) and braids with $\Phi$ via the exact $S_3 = \mathbb{Z}_3 \rtimes \mathbb{Z}_2$ relation $\Phi \omega_J = \overline{\omega}_J \Phi$; (6) a 5-graded Kantor--Koecher--Tits and $\mathfrak{su}(3)$ color tripotent master equation ($\mathrm{ad}_T^5 - 5\mathrm{ad}_T^3 + 4\mathrm{ad}_T = 0$) with $W_{12}/W_{24}$ Vandermonde projectors; and (7) an algebraic Wilson plaquette and entanglement area law. Every theorem is decided in a single line by a confluent right-associative Knuth--Bendix rewrite macro (\texttt{peirce\_abel}) for the two-sided ideal $\langle P^2 - P \rangle$.
\end{abstract}

\section{The Premise: Operationalizing the Scalar Crutches}
For a century, quantum theory operationalized classical phase-space coordinates into non-commuting operators while leaving the background mathematical scaffolding—the imaginary unit $i$, the mass-squared scale $m^2$, the Fubini--Study metric $g_{\mu\nu}$, and the partition function $Z$—as commuting scalar numbers.

In this note, we work over an arbitrary associative ring $B$ (with no scalar field $\mathbb{R}$ or $\mathbb{C}$, no division, and no commutativity assumptions) equipped with a single binary idempotent $P^2 = P$ and the non-linear \emph{idempotency defect map}:
\begin{equation}
  \delta(X) := X^2 - X, \qquad \bar{\delta}(X) := \delta(-X) = X^2 + X, \qquad \delta(-X)\,\delta(X) = \delta(X^2).
\end{equation}
From $\delta(P) = 0$ and any two ring elements $A, C \in B$, define the grading involution $S = P - (1 - P)$ ($S^2 = 1$) and the square-zero Peirce boundary cones:
\begin{equation}
  N_+ := P A (1 - P), \qquad N_- := (1 - P) C P \qquad (N_+^2 = N_-^2 = 0).
\end{equation}
The symmetric and antisymmetric combinations of $N_+$ and $N_-$ generate the \textbf{Tetraktys} $(\Phi, J, V, \Sigma)$:
\begin{equation}
  \Phi := N_+ + N_-, \qquad J := N_+ - N_-, \qquad V := \{N_+, N_-\} = Q_+ + Q_-, \qquad \Sigma := [N_+, N_-] = Q_+ - Q_-,
\end{equation}
where $Q_+ := N_+ N_- \in P B P$ ($\star Q_+ := S Q_+ = +Q_+$, self-dual instanton sector) and $Q_- := N_- N_+ \in (1-P) B (1-P)$ ($\star Q_- = -Q_-$, anti-self-dual sector) are the chiral halves of the Operator Quantum Geometric Tensor ($Q_+ Q_- = Q_- Q_+ = 0$).

\section{Eight Machine-Verified Structural Theorems}

All eight theorems below hold identically for all $A, C, X \in B$ whenever $P^2 = P$, and are proved in one tactic call by \texttt{peirce\_abel} in Lean~4:

\begin{theorem}[Emergent $\mathcal{C}\ell_{1,1}$ Phase Axis \& Vertical Grade Generator $\delta$]
The Tetraktys satisfies $\Phi^2 = +V$, $J^2 = -V$, $\Phi^2 + J^2 = 0$, $\{ \Phi, J \} = 0$, $J \Phi = -\Phi J = \Sigma = S V$, and $[N_\pm, V] = 0$. Moreover, $\delta$ polarizes to the Jordan bracket $\delta(X + Y) - \delta(X) - \delta(Y) = \{X, Y\}$ and acts as a vertical grade generator jumping from the odd tangent space $\mathfrak{p} = B_{10} \oplus B_{01}$ to the even core $\mathfrak{k} = B_{11} \oplus B_{00}$:
\begin{equation}
  \delta(P + \Phi) = +V, \qquad \delta(P + J) = -V, \qquad \delta(P + [P, A]) = [P, A]^2, \qquad \delta(-\Phi)\,\delta(\Phi) = (V + \Phi)(V - \Phi) = \delta(V).
\end{equation}
\end{theorem}

\begin{theorem}[Double-Derivation Dissipator Trinity \& The $-4V$ Gap]
Define the cross-cone sandwich $\Phi_{\mathrm{sym}}(X) = N_+ X N_- + N_- X N_+$ and phase-conjugate sandwich $\Psi_{\mathrm{pc}}(X) = N_+ X N_+ + N_- X N_-$. Then $\Phi_{\mathrm{sym}}(X) + \Psi_{\mathrm{pc}}(X) = \Phi X \Phi$, $\Phi_{\mathrm{sym}}(X) - \Psi_{\mathrm{pc}}(X) = -J X J$, and the double derivations $\mathcal{M}_\Phi(X) = -[\Phi, [\Phi, X]]$, $\mathcal{M}_J(X) = +[J, [J, X]]$, $\mathcal{M}_\Sigma(X) = -[\Sigma, [\Sigma, X]]$ satisfy:
\begin{equation}
  -2\big([N_+, [N_-, X]] + [N_-, [N_+, X]]\big) = \mathcal{M}_\Phi(X) + \mathcal{M}_J(X), \qquad \mathcal{M}_\Phi(X) - \mathcal{M}_J(X) = 4\,\Psi_{\mathrm{pc}}(X),
\end{equation}
with $\mathcal{M}_\Phi(V) = \mathcal{M}_\Phi(\Phi) = 0$ (dark kernel) and $\mathcal{M}_\Phi(J) = -4VJ$, $\mathcal{M}_\Phi(\Sigma) = -4V\Sigma$ (gapped sector).
\end{theorem}

\begin{theorem}[Universal Off-Shell Homogenized Klein--Hadamard Projectors]
Whereas $\mathcal{M}_\Phi$ and $\mathcal{M}_J$ scale as $V^1$ and $\mathcal{M}_\Sigma$ scales as $V^2$ (differing by the second iterate $\delta(\delta(P+\Phi)) = \delta(V) = V^2 - V$), the homogenized superoperators
\begin{align}
  \widetilde{\Pi}_V(X) &:= 8 V^2 X + V\mathcal{M}_\Phi(X) + V\mathcal{M}_J(X) + \mathcal{M}_\Sigma(X), &
  \widetilde{\Pi}_\Phi(X) &:= V\mathcal{M}_\Phi(X) - V\mathcal{M}_J(X) - \mathcal{M}_\Sigma(X), \nonumber \\
  \widetilde{\Pi}_J(X) &:= V\mathcal{M}_J(X) - V\mathcal{M}_\Phi(X) - \mathcal{M}_\Sigma(X), &
  \widetilde{\Pi}_\Sigma(X) &:= \mathcal{M}_\Sigma(X) - V\mathcal{M}_\Phi(X) - V\mathcal{M}_J(X)
\end{align}
sum to $8V^2 X$, coincide on $(V, \Phi, J, \Sigma)$ with the Fourier character sums of the multiplicative Galois group $\mathrm{Gal} \cong \mathbb{Z}_2 \times \mathbb{Z}_2$ ($\mathcal{G}_1(X) = V^2 X$, $\mathcal{G}_\Phi(X) = V\Phi X \Phi$, $\mathcal{G}_J(X) = -V J X J$, $\mathcal{G}_\Sigma(X) = \Sigma X \Sigma$), commute with Weyl conjugation $X \mapsto J X (-J)$, and satisfy exact off-shell orthogonality $\widetilde{\Pi}_\alpha(\widetilde{\Pi}_\beta(G_\beta)) = 8\delta_{\alpha\beta} V^2 \widetilde{\Pi}_\alpha(G_\beta)$ for $G_\beta \in \{V, \Phi, J, \Sigma\}$.
\end{theorem}

\begin{theorem}[Division-Free Hodge--De~Rham Cochain Complex \& $\bar{d} = -\star d \star$]
Let $\tau(X) = S X S$ and $\star X = S X$. The graded coboundary $d_\pm(X) := N_\pm X - \tau(X) N_\pm$ and boundary codifferential $\bar{d}_\pm(X) := N_\pm X + \tau(X) N_\pm = -\star d_\pm(\star X)$ satisfy $d_+^2(X) = d_-^2(X) = \bar{d}_+^2(X) = \bar{d}_-^2(X) = 0$ for all $X \in B$, and the chiral Hodge--Dirac Laplacians ($d_\Phi = d_+ + d_-$, $d_J = d_+ - d_-$) generate pure left-multiplication by $2V$, $2\Sigma$, and $2Q_\pm$:
\begin{equation}
  \{d_\Phi, \bar{d}_\Phi\}(X) = 2 V X, \qquad \{d_J, \bar{d}_\Phi\}(X) = 2 \Sigma X, \qquad (d_+ \bar{d}_- + \bar{d}_+ d_-)(X) = 2 Q_+ X \qquad \forall X \in B.
\end{equation}
\end{theorem}

\begin{theorem}[Operator Möbius--Bruhat Group, Cross-Ratio \& Bergman--Euler Zeta Factor]
For the Grassmannian idempotents $P_A = (1 + N_+)P(1 - N_+) = P - N_+$ and $P_C = (1 + N_-)P(1 - N_-) = P + N_-$, the chord is $P_C - P_A = \Phi$, the Fubini--Study squared distance is $(P_C - P_A)^2 = V$, the non-commutative cross-ratio $\{P - P_A, P - P_C\} = -V$ is invariant under the Möbius--Bruhat group $g_+ = (1 + N_+)(1 - N_-)$, and the Bergman--Euler inverse Zeta factor $1 - (P_A - P_C)^2 = 1 - V$ factors into commuting chiral primes:
\begin{equation}
  1 - V = (1 - Q_+)(1 - Q_-) = (1 - \Phi)(1 + \Phi) = \Phi_4(J), \qquad 1 + V = (1 + Q_+)(1 + Q_-) = (S + \Phi)^2 = \Phi_4(\Phi).
\end{equation}
\end{theorem}

\begin{theorem}[Operator Cyclotomics \& The Explicit $S_3 = \mathbb{Z}_3 \rtimes \mathbb{Z}_2$ Galois Group]
Inside $B$, the Golden transfer operator $\mathcal{T}_\Phi = P + \Phi$ has discriminant $(2\mathcal{T}_\Phi - 1)^2 = (S + 2\Phi)^2 = 1 + 4V$, whereas $\zeta_J = P + J$ has Eisenstein discriminant $(2\zeta_J - 1)^2 = (S + 2J)^2 = 1 - 4V$ and satisfies $\Phi_6(\zeta_J) = 1 - V$. The operator cube root $\omega_J := -(P + J)$ and its conjugate $\overline{\omega}_J := -(1 - P) + J$ satisfy $\Phi_3(\omega_J) = 1 - V$, $\omega_J^3 - 1 = (\omega_J - 1)(1 - V)$, and form an exact off-shell $S_3 = \mathbb{Z}_3 \rtimes \mathbb{Z}_2$ algebra with $\Phi$:
\begin{equation}
  1 + \omega_J + \overline{\omega}_J = 0, \qquad \omega_J \overline{\omega}_J = \overline{\omega}_J \omega_J = +V, \qquad \Phi\,\omega_J = \overline{\omega}_J\,\Phi, \qquad \Phi\,\overline{\omega}_J = \omega_J\,\Phi.
\end{equation}
\end{theorem}

\begin{theorem}[5-Graded Kantor--Koecher--Tits \& 3-Color $\mathfrak{su}(3)$ Tripotent Closure ($W_{12}/W_{24}$)]
Both the superoperator grading $\Delta_P(\mathcal{K})(X) = [P, \mathcal{K}(X)] - \mathcal{K}([P, X])$ on $\mathcal{K}_{\mathrm{tot}} = \sum_{m=-2}^{+2} \mathcal{G}_m$ and the inner derivation $\mathrm{ad}_T(X) = [T, X]$ of a 3-color tripotent $T = P_R - P_G$ ($T^3 = T$, where $2P_R = \bar{\delta}(T)$, $2P_G = \delta(T)$, $P_B = 1 - T^2$) satisfy the 5-graded master equation:
\begin{equation}
  \Delta_P^5 - 5\,\Delta_P^3 + 4\,\Delta_P = 0, \qquad \mathrm{ad}_T^5(X) - 5\,\mathrm{ad}_T^3(X) + 4\,\mathrm{ad}_T(X) = 0 \qquad \forall X \in B,
\end{equation}
whose Vandermonde inversion isolates all five grades at the ternary Golay scale $12$ and binary Golay / Leech scale $24$.
\end{theorem}

\begin{theorem}[Wilson Plaquette Action \& Exact Entanglement Area Law]
For the 4-link Wilson plaquette $U_\square = (1 + N_+)(1 + N_-)(1 - N_+)(1 - N_-)$, the physical even projection satisfies $\mathrm{evenGrade}_P((1 - U_\square) + (1 - U_\square^{\mathrm{rev}})) = 2V$ and $\mathrm{evenGrade}_P(U_\square - U_\square^{\mathrm{rev}}) = 2\Sigma$. Moreover, adding arbitrary bulk interior/exterior operators $\mathrm{evenGrade}_P(U)$ to $A$ and $C$ leaves $N_\pm$, $V$, $\Sigma$, $\delta(P + \Phi) = V$, and $\mathcal{M}_\Phi(X)$ strictly unchanged (exact boundary area law).
\end{theorem}

\section{The Confluent Knuth--Bendix Proof Engine in Lean 4}
In Lean~4, \texttt{mul\_assoc} normalizes non-commutative products into right-associated trees $X_1 * (X_2 * (\cdots * X_k))$, hiding internal occurrences of $P * P$ inside $P * (P * X)$. Adjoining the single confluence lemma
